import pandas as pd
import pytz
from datetime import datetime
from random import randint, seed as set_seed


def task_func(
    utc_datetime,
    cities=['New York', 'London', 'Beijing', 'Tokyo', 'Sydney'],
    weather_conditions=['Sunny', 'Cloudy', 'Rainy', 'Snowy', 'Stormy'],
    timezones={
        'New York': 'America/New_York',
        'London': 'Europe/London',
        'Beijing': 'Asia/Shanghai',
        'Tokyo': 'Asia/Tokyo',
        'Sydney': 'Australia/Sydney'
    },
    seed=42
):
    def _is_nonempty_str(value):
        return isinstance(value, str) and value != ""

    if not isinstance(utc_datetime, datetime):
        raise ValueError("utc_datetime must be a datetime object")

    if not isinstance(cities, (list, tuple)) or not all(_is_nonempty_str(city) for city in cities):
        raise ValueError("cities must be a list or tuple of non-empty strings")

    if not isinstance(weather_conditions, (list, tuple)) or len(weather_conditions) == 0 or not all(
        _is_nonempty_str(condition) for condition in weather_conditions
    ):
        raise ValueError("weather_conditions must be a non-empty list or tuple of non-empty strings")

    if not isinstance(timezones, dict) or not all(
        _is_nonempty_str(city) and _is_nonempty_str(tz_name) for city, tz_name in timezones.items()
    ):
        raise ValueError("timezones must be a dictionary mapping city names to timezone strings")

    if not isinstance(seed, int) or isinstance(seed, bool):
        raise ValueError("seed must be an integer")

    for city in cities:
        if city not in timezones:
            raise ValueError(f"Missing timezone for city: {city}")
        try:
            pytz.timezone(timezones[city])
        except Exception as exc:
            raise ValueError(f"Invalid timezone for city: {city}") from exc

    set_seed(seed)

    if utc_datetime.tzinfo is None or utc_datetime.tzinfo.utcoffset(utc_datetime) is None:
        utc_dt = pytz.UTC.localize(utc_datetime)
    else:
        utc_dt = utc_datetime.astimezone(pytz.UTC)

    rows = []
    for city in cities:
        tz = pytz.timezone(timezones[city])
        local_dt = utc_dt.astimezone(tz)
        local_time = local_dt.strftime("%Y-%m-%d %H:%M:%S %Z")
        weather = weather_conditions[randint(0, len(weather_conditions) - 1)]
        rows.append(
            {
                "City": city,
                "Local Time": local_time,
                "Weather Condition": weather,
            }
        )

    return pd.DataFrame(rows, columns=["City", "Local Time", "Weather Condition"])
